# Terraform Refactor: Single Module with `for_each`

## Directory Structure

```
.
├── main.tf
├── variables.tf
├── outputs.tf
├── terraform.tfvars          # shared defaults
├── dev.tfvars
├── prod.tfvars
├── moved.tf                  # state moves (zero-diff)
└── modules/
    └── env/
        ├── main.tf
        ├── variables.tf
        ├── outputs.tf
        └── terraform.tf
```

---

## `variables.tf` (root)

```hcl
variable "environments" {
  description = "Map of environments to deploy. Key = env name, value = env-specific config."
  type = map(object({
    region            = string
    vpc_cidr          = string
    eks_node_count    = number
    eks_instance_type = string
    rds_instance_type = string
    rds_multi_az      = bool
    rds_encrypted     = bool
    rds_backup_days   = number
    s3_replicate      = bool
    s3_replica_region = optional(string, "")
    iam_uses_oidc     = bool
    iam_oidc_provider = optional(string, "")
    https_type        = string  # "alb" | "cloudfront"
    acm_region        = optional(string, "")
  }))
  default = {}
}
```

---

## `dev.tfvars`

```hcl
environments = {
  dev = {
    region            = "us-east-1"
    vpc_cidr          = "10.0.0.0/16"
    eks_node_count    = 2
    eks_instance_type = "t3.medium"
    rds_instance_type = "db.t3.micro"
    rds_multi_az      = false
    rds_encrypted     = false
    rds_backup_days   = 7
    s3_replicate      = false
    iam_uses_oidc     = false
    https_type        = "alb"
  }
}
```

---

## `prod.tfvars`

```hcl
environments = {
  prod = {
    region            = "us-east-1"
    vpc_cidr          = "10.1.0.0/16"
    eks_node_count    = 4
    eks_instance_type = "t3.large"
    rds_instance_type = "db.t3.medium"
    rds_multi_az      = true
    rds_encrypted     = true
    rds_backup_days   = 14
    s3_replicate      = true
    s3_replica_region = "us-west-2"
    iam_uses_oidc     = true
    iam_oidc_provider = "arn:aws:iam::123456789012:oidc-provider/oidc.eks.us-east-1.amazonaws.com/id/EXAMPLE"
    https_type        = "cloudfront"
    acm_region        = "us-east-1"
  }
}
```

---

## `main.tf` (root)

```hcl
terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

# ─── Per-environment provider (state isolation) ───────────────────────
provider "aws" {
  for_each = var.environments
  region   = each.value.region

  default_tags {
    tags = {
      Environment = each.key
      ManagedBy   = "terraform"
    }
  }
}

module "env" {
  source   = "./modules/env"
  for_each = var.environments

  # Identity
  env_name = each.key
  region   = each.value.region

  # Network
  vpc_cidr = each.value.vpc_cidr

  # EKS
  eks_node_count    = each.value.eks_node_count
  eks_instance_type = each.value.eks_instance_type

  # RDS
  rds_instance_type = each.value.rds_instance_type
  rds_multi_az      = each.value.rds_multi_az
  rds_encrypted     = each.value.rds_encrypted
  rds_backup_days   = each.value.rds_backup_days

  # S3
  s3_replicate      = each.value.s3_replicate
  s3_replica_region = each.value.s3_replica_region

  # IAM
  iam_uses_oidc     = each.value.iam_uses_oidc
  iam_oidc_provider = each.value.iam_oidc_provider

  # HTTPS
  https_type = each.value.https_type
  acm_region = each.value.acm_region

  # Pass the correct provider alias
  provider = aws[each.key]
}
```

---

## `outputs.tf` (root)

```hcl
output "endpoints" {
  description = "Per-environment outputs"
  value       = { for k, m in module.env : k => m.outputs }
}
```

