## `modules/env/variables.tf`

```hcl
variable "env_name" {
  type        = string
  description = "Environment identifier (dev, prod)"
}

variable "region" {
  type        = string
}

variable "vpc_cidr" {
  type        = string
}

variable "eks_node_count" {
  type        = number
}

variable "eks_instance_type" {
  type        = string
}

variable "rds_instance_type" {
  type        = string
}

variable "rds_multi_az" {
  type        = bool
}

variable "rds_encrypted" {
  type        = bool
}

variable "rds_backup_days" {
  type        = number
}

variable "s3_replicate" {
  type        = bool
}

variable "s3_replica_region" {
  type        = string
  default     = ""
}

variable "iam_uses_oidc" {
  type        = bool
}

variable "iam_oidc_provider" {
  type        = string
  default     = ""
}

variable "https_type" {
  type        = string
  validation {
    condition     = contains(["alb", "cloudfront"], var.https_type)
    error_message = "https_type must be 'alb' or 'cloudfront'"
  }
}

variable "acm_region" {
  type    = string
  default = ""
}
```

---

## `modules/env/main.tf`

```hcl
# ─── Data Sources ──────────────────────────────────────────────────────

data "aws_caller_identity" "current" {}

data "aws_eks_cluster_auth" "this" {
  name = module.eks.cluster_name
}

data "aws_vpc" "this" {
  filter {
    name   = "cidr"
    values = [var.vpc_cidr]
  }
}

data "aws_subnets" "this" {
  filter {
    name   = "vpc-id"
    values = [data.aws_vpc.this.id]
  }
}

# ─── VPC (assumed pre-existing or imported; minimal here) ─────────────
# In a real setup you'd import or use a separate network module.
# We reference it via data source above.

# ─── EKS ───────────────────────────────────────────────────────────────

module "eks" {
  source  = "terraform-aws-modules/eks/aws"
  version = "~> 20.0"

  cluster_name    = "${var.env_name}-app"
  cluster_version = "1.30"

  cluster_endpoint_public_access = true

  vpc_id     = data.aws_vpc.this.id
  subnet_ids = data.aws_subnets.this.ids

  eks_managed_node_groups = {
    main = {
      min_size     = 1
      max_size     = var.eks_node_count
      desired_size = var.eks_node_count
      instance_type = var.eks_instance_type
    }
  }

  tags = {
    Environment = var.env_name
  }
}

# ─── S3 ────────────────────────────────────────────────────────────────

resource "aws_s3_bucket" "assets" {
  bucket = "${var.env_name}-app-assets-${data.aws_caller_identity.current.account_id}"

  tags = {
    Environment = var.env_name
  }
}

resource "aws_s3_bucket_versioning" "assets" {
  bucket = aws_s3_bucket.assets.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "assets" {
  bucket = aws_s3_bucket.assets.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "aws:kms"
    }
  }
}

resource "aws_s3_bucket_public_access_block" "assets" {
  bucket = aws_s3_bucket.assets.id

  block_public_acls       = true
  block_public_policy     = true
  block_public_buckets    = true
  ignore_public_acls      = true
}

# Cross-region replication (prod only)
resource "aws_s3_bucket_replication_configuration" "assets" {
  count  = var.s3_replicate ? 1 : 0
  bucket = aws_s3_bucket.assets.id

  role = aws_iam_role.s3_replication.arn

  rules {
    prefix = ""
    status = "Enabled"

    destination {
      bucket        = "arn:aws:s3:::${aws_s3_bucket.replica.bucket}"
      storage_class = "STANDARD"
    }
  }
}

resource "aws_s3_bucket" "replica" {
  count  = var.s3_replicate ? 1 : 0
  bucket = "${var.env_name}-app-assets-replica-${data.aws_caller_identity.current.account_id}"

  tags = {
    Environment = var.env_name
  }
}

resource "aws_s3_bucket_versioning" "replica" {
  count  = var.s3_replicate ? 1 : 0
  bucket = aws_s3_bucket.replica[0].id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_iam_role" "s3_replication" {
  count = var.s3_replicate ? 1 : 0

  name = "${var.env_name}-s3-replication-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Principal = {
        Service = "s3.amazonaws.com"
      }
      Action = "sts:AssumeRole"
    }]
  })
}

resource "aws_iam_role_policy" "s3_replication" {
  count  = var.s3_replicate ? 1 : 0
  role   = aws_iam_role.s3_replication[0].id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "s3:GetReplicationConfiguration",
          "s3:ListBucket"
        ]
        Resources = [aws_s3_bucket.assets.arn]
      },
      {
        Effect = "Allow"
        Action = [
          "s3:GetObjectVersion",
          "s3:PutObject"
        ]
        Resources = ["${aws_s3_bucket.replica[0].arn}/*"]
      },
      {
        Effect = "Allow"
        Action = [
          "kms:GenerateDataKey",
          "kms:Decrypt"
        ]
        Resources = [aws_kms_key.assets.arn]
      }
    ]
  })
}

# KMS key for S3
resource "aws_kms_key" "assets" {
  description             = "KMS key for ${var.env_name} app assets bucket"
  deletion_window_in_days = 30

  tags = {
    Environment = var.env_name
  }
}

# ─── RDS ───────────────────────────────────────────────────────────────

resource "aws_db_subnet_group" "this" {
  name       = "${var.env_name}-app-db"
  subnet_ids = data.aws_subnets.this.ids

  tags = {
    Environment = var.env_name
  }
}

resource "aws_security_group" "rds" {
  name   = "${var.env_name}-app-rds-sg"
  vpc_id = data.aws_vpc.this.id

  ingress {
    description = "PostgreSQL from EKS nodes"
    from_port   = 5432
    to_port     = 5432
    protocol    = "tcp"
    # In production, reference the EKS node security group here
    cidr_blocks = [var.vpc_cidr]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Environment = var.env_name
  }
}

resource "aws_db_instance" "postgres" {
  identifier     = "${var.env_name}-app-db"
  engine         = "postgres"
  engine_version = "16"
  instance_class = var.rds_instance_type

  allocated_storage     = 20
  max_allocated_storage = 100
  storage_type          = "gp3"
  storage_encrypted     = var.rds_encrypted

  multi_az       = var.rds_multi_az
  db_name        = "appdb"
  username       = "appuser"
  password       = random_password.db_password.result
  db_subnet_group_name   = aws_db_subnet_group.this.name
  vpc_security_group_ids = [aws_security_group.rds.id]

  backup_retention_period = var.rds_backup_days
  deletion_protection     = true
  publicly_accessible     = false
  skip_final_snapshot     = false
  final_snapshot_identifier = "${var.env_name}-app-db-final"

  maintenance_window = "sun:03:00-sun:04:30"
  backup_window      = "sun:04:30-sun:05:30"
  parameter_group_name = "default.postgres16"

  tags = {
    Environment = var.env_name
  }
}

resource "random_password" "db_password" {
  length  = 20
  special = false
}

# ─── IAM (Service Account) ─────────────────────────────────────────────

resource "aws_iam_role" "service_account" {
  name = "${var.env_name}-app-service-account"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        # Prod: OIDC federation (no long-lived credentials)
        # Dev: EKS pod identity or simpler trust
        Principal = var.iam_uses_oidc ? {
          Federated = [var.iam_oidc_provider]
        } : {
          Service = "ec2.amazonaws.com"
        }
        Action = "sts:AssumeRole"
        Condition = var.iam_uses_oidc ? {
          StringEquals = {
            "${replace(var.iam_oidc_provider, "arn:aws:iam::${data.aws_caller_identity.current.account_id}:", "")}:sub" = "system:serviceaccount:default:app"
          }
        } : {}
      }
    ]
  })

  tags = {
    Environment = var.env_name
  }
}

# Least-privilege policy: scoped to this env's resources only
resource "aws_iam_role_policy" "service_account" {
  name = "app-service-policy"
  role = aws_iam_role.service_account.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "S3AssetsReadWrite"
        Effect = "Allow"
        Action = [
          "s3:GetObject",
          "s3:PutObject",
          "s3:ListBucket"
        ]
        Resources = [
          aws_s3_bucket.assets.arn,
          "${aws_s3_bucket.assets.arn}/*"
        ]
      },
      {
        Sid    = "KMSDecrypt"
        Effect = "Allow"
        Action = [
          "kms:Decrypt",
          "kms:GenerateDataKey"
        ]
        Resources = [aws_kms_key.assets.arn]
      },
      {
        # No wildcard actions — explicitly scoped
        Sid    = "SecretsManagerRead"
        Effect = "Allow"
        Action = [
          "secretsmanager:GetSecretValue"
        ]
        Resources = ["arn:aws:secretsmanager:*:*:secret:${var.env_name}/app-db*"]
      }
    ]
  })
}

# ─── HTTPS ─────────────────────────────────────────────────────────────

# --- ALB (dev) ---
resource "aws_lb" "this" {
  count  = var.https_type == "alb" ? 1 : 0
  name   = "${var.env_name}-app-alb"
  type   = "application"
  subnets = data.aws_subnets.this.ids

  security_groups = [aws_security_group.alb.id]
  internal        = true  # dev = internal

  tags = {
    Environment = var.env_name
  }
}

resource "aws_security_group" "alb" {
  count  = var.https_type == "alb" ? 1 : 0
  name   = "${var.env_name}-app-alb-sg"
  vpc_id = data.aws_vpc.this.id

  ingress {
    description = "HTTPS"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = [var.vpc_cidr]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_lb_listener" "https" {
  count         = var.https_type == "alb" ? 1 : 0
  load_balancer_arn = aws_lb.this[0].arn
  port          = 443
  protocol      = "HTTPS"
  ssl_policy    = "ELBSecurityPolicy-TLS12-2017-01"
  certificate_arn = var.https_type == "alb" ? aws_acm_certificate.this[0].arn : null

  default_action {
    type             = "fixed-response"
    fixed_response {
      content_type = "text/plain"
      message_body = "Hello from ${var.env_name}"
      status_code  = "200"
    }
  }
}

# --- CloudFront (prod) ---
resource "aws_cloudfront_distribution" "this" {
  count = var.https_type == "cloudfront" ? 1 : 0

  origin {
    domain_name              = aws_lb.prod_origin[0].dns_name
    origin_id                = "${var.env_name}-origin"
    custom_origin_config {
      domain_name              = aws_lb.prod_origin[0].dns_name
      origin_protocol_policy   = "https-only"
      origin_ssl_protocols     = ["TLSv1.2", "TLSv1.3"]
    }
  }

  enabled             = true
  is_ipv6_enabled     = true
  price_class         = "PriceClass_100"
  default_root_object = "index.html"

  default_cache_behavior {
    target_origin_id       = "${var.env_name}-origin"
    viewer_protocol_policy = "redirect-to-https"
    allowed_methods        = ["GET", "HEAD", "OPTIONS"]
    cached_methods         = ["GET", "HEAD"]
    cache_policy_id        = "658327ea-f89d-4fab-a63d-7e88631ecef8" # CacheQueryString false
    compress               = true
  }

  viewer_certificate {
    acm_certificate_arn = aws_acm_certificate.us_east_1[0].arn
    ssl_support_method  = "sni-only"
  }

  restrictions {
    geo_restriction {
      restriction_type = "none"
    }
  }

  tags = {
    Environment = var.env_name
  }
}

# Prod needs a public-facing LB as origin for CloudFront
resource "aws_lb" "prod_origin" {
  count  = var.https_type == "cloudfront" ? 1 : 0
  name   = "${var.env_name}-app-origin-alb"
  type   = "application"
  subnets = data.aws_subnets.this.ids

  security_groups = [aws_security_group.prod_origin.id]
  internal        = false

  tags = {
    Environment = var.env_name
  }
}

resource "aws_security_group" "prod_origin" {
  count  = var.https_type == "cloudfront" ? 1 : 0
  name   = "${var.env_name}-app-origin-sg"
  vpc_id = data.aws_vpc.this.id

  ingress {
    description     = "HTTPS from CloudFront"
    from_port       = 443
    to_port         = 443
    protocol        = "tcp"
    security_groups = [] # In practice: CloudFront SG or CIDR
    cidr_blocks     = [var.vpc_cidr]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_lb_listener" "origin_https" {
  count         = var.https_type == "cloudfront" ? 1 : 0
  load_balancer_arn = aws_lb.prod_origin[0].arn
  port          = 443
  protocol      = "HTTPS"
  ssl_policy    = "ELBSecurityPolicy-TLS12-2017-01"
  certificate_arn = aws_acm_certificate.this[0].arn

  default_action {
    type             = "fixed-response"
    fixed_response {
      content_type = "text/plain"
      message_body = "Hello from ${var.env_name}"
      status_code  = "200"
    }
  }
}

# ─── ACM Certificates ──────────────────────────────────────────────────

# Regional cert (for ALB)
resource "aws_acm_certificate" "this" {
  count             = var.https_type == "alb" ? 1 : 0
  domain_name       = "${var.env_name}.example.com"
  validation_method = "DNS"

  lifecycle {
    create_before_destroy = true
  }
}

# us-east-1 cert (for CloudFront)
resource "aws_acm_certificate" "us_east_1" {
  count             = var.https_type == "cloudfront" ? 1 : 0
  domain_name       = "${var.env_name}.example.com"
  validation_method = "DNS"

  provider = aws["us-east-1"]  # CloudFront requires us-east-1 / us-west-2

  lifecycle {
    create_before_destroy = true
  }
}

# ─── Secret (DB connection string) ─────────────────────────────────────

# The secret is stored externally (SOPS, Vault, etc.) and injected at
# apply time via -var-file or the sops provider. We reference it here
# as a variable to keep it out of state plaintext.

variable "db_connection_string" {
  type        = string
  sensitive   = true
  description = "DB connection string. Provide via -var-file or SOPS."
}

resource "null_resource" "seed_secret" {
  triggers = {
    env = var.env_name
  }
}
```

