## `modules/env/outputs.tf`

```hcl
output "cluster_name" {
  value = module.eks.cluster_name
}

output "cluster_endpoint" {
  value = module.eks.cluster_endpoint
}

output "s3_bucket" {
  value = aws_s3_bucket.assets.id
}

output "rds_endpoint" {
  value     = aws_db_instance.postgres.endpoint
  sensitive = true
}

output "rds_address" {
  value     = aws_db_instance.postgres.address
  sensitive = true
}

output "alb_dns" {
  value = var.https_type == "alb" ? aws_lb.this[0].dns_name : null
}

output "cloudfront_domain" {
  value = var.https_type == "cloudfront" ? aws_cloudfront_distribution.this[0].domain_name : null
}

output "iam_role_arn" {
  value = aws_iam_role.service_account.arn
}
```

